window.ENTRY_ASSETS["lp-local-llm-v2--gemini-4-argon-cli--1792932949881-fj7tj"]={"html":"\u003c!doctype html>\n\u003chtml lang=\"ja\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n\u003ctitle>LOCAL LLM // 手元の計算機で思考する知性\u003c/title>\n\u003cstyle>\n  :root {\n    --bg-base: #07090e;\n    --bg-surface: #0e131d;\n    --bg-surface-elevated: #151c2c;\n    --bg-glass: rgba(14, 19, 29, 0.78);\n    --text-primary: #f0f4f8;\n    --text-secondary: #9ba8bc;\n    --text-muted: #64748b;\n    --accent-cyan: #00f0ff;\n    --accent-amber: #ffb800;\n    --accent-emerald: #10b981;\n    --accent-rose: #f43f5e;\n    --border-dim: rgba(148, 163, 184, 0.14);\n    --border-bright: rgba(0, 240, 255, 0.45);\n    --glow-cyan: 0 0 28px rgba(0, 240, 255, 0.22);\n    --font-sans: \"Hiragino Kaku Gothic ProN\", \"Hiragino Sans\", \"Yu Gothic UI\", \"Meiryo\", system-ui, -apple-system, sans-serif;\n    --font-mono: \"JetBrains Mono\", \"SFMono-Regular\", Consolas, \"Liberation Mono\", Menlo, monospace;\n    --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);\n  }\n\n  *, *::before, *::after {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n  }\n\n  html {\n    scroll-behavior: smooth;\n    background-color: var(--bg-base);\n    color: var(--text-primary);\n    font-family: var(--font-sans);\n    line-height: 1.7;\n    -webkit-font-smoothing: antialiased;\n  }\n\n  body {\n    overflow-x: hidden;\n    position: relative;\n    background-color: var(--bg-base);\n    background-image: \n      radial-gradient(circle at 15% 15%, rgba(0, 240, 255, 0.06) 0%, transparent 45%),\n      radial-gradient(circle at 85% 80%, rgba(255, 184, 0, 0.05) 0%, transparent 45%);\n  }\n\n  /* Subtle Structural Grid Overlay */\n  .grid-backdrop {\n    position: fixed;\n    inset: 0;\n    pointer-events: none;\n    z-index: 0;\n    background-size: 48px 48px;\n    background-image: \n      linear-gradient(to right, rgba(255, 255, 255, 0.025) 1px, transparent 1px),\n      linear-gradient(to bottom, rgba(255, 255, 255, 0.025) 1px, transparent 1px);\n    mask-image: radial-gradient(circle at 50% 35%, black 30%, transparent 90%);\n  }\n\n  /* Scroll Progress Bar */\n  .scroll-progress-track {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 3px;\n    background: rgba(255, 255, 255, 0.05);\n    z-index: 1000;\n  }\n  .scroll-progress-bar {\n    height: 100%;\n    width: 0%;\n    background: linear-gradient(90deg, var(--accent-cyan), var(--accent-amber));\n    box-shadow: 0 0 12px var(--accent-cyan);\n    transition: width 0.08s linear;\n  }\n\n  /* Header / Navigation */\n  .site-header {\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    z-index: 900;\n    backdrop-filter: blur(14px);\n    -webkit-backdrop-filter: blur(14px);\n    background: rgba(7, 9, 14, 0.75);\n    border-bottom: 1px solid var(--border-dim);\n  }\n  .header-inner {\n    max-width: 1200px;\n    margin: 0 auto;\n    padding: 0.85rem 1.5rem;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 1rem;\n  }\n  .brand {\n    display: flex;\n    align-items: center;\n    gap: 0.65rem;\n    text-decoration: none;\n    color: var(--text-primary);\n    font-family: var(--font-mono);\n    font-weight: 700;\n    font-size: 0.95rem;\n    letter-spacing: 0.06em;\n  }\n  .brand-dot {\n    width: 10px;\n    height: 10px;\n    border-radius: 2px;\n    background: var(--accent-cyan);\n    box-shadow: 0 0 10px var(--accent-cyan);\n    display: inline-block;\n    position: relative;\n  }\n  .brand-dot::after {\n    content: \"\";\n    position: absolute;\n    inset: -4px;\n    border: 1px solid var(--accent-cyan);\n    border-radius: 4px;\n    opacity: 0.5;\n    animation: pulseRing 2.6s infinite var(--ease-out-expo);\n  }\n  .nav-links {\n    display: flex;\n    align-items: center;\n    gap: 1.5rem;\n    list-style: none;\n  }\n  .nav-links a {\n    color: var(--text-secondary);\n    text-decoration: none;\n    font-size: 0.85rem;\n    font-weight: 600;\n    transition: color 0.2s ease;\n    padding: 0.25rem 0.4rem;\n    border-radius: 4px;\n  }\n  .nav-links a:hover,\n  .nav-links a:focus-visible {\n    color: var(--accent-cyan);\n    outline: none;\n  }\n  .nav-links a:focus-visible {\n    box-shadow: 0 0 0 2px var(--accent-cyan);\n  }\n  .status-pill {\n    font-family: var(--font-mono);\n    font-size: 0.72rem;\n    padding: 0.25rem 0.65rem;\n    border-radius: 999px;\n    background: rgba(16, 185, 129, 0.12);\n    border: 1px solid rgba(16, 185, 129, 0.35);\n    color: #34d399;\n    display: flex;\n    align-items: center;\n    gap: 0.4rem;\n    white-space: nowrap;\n  }\n  .status-pill::before {\n    content: \"\";\n    width: 6px;\n    height: 6px;\n    border-radius: 50%;\n    background: #10b981;\n  }\n\n  /* Layout Utilities */\n  main {\n    position: relative;\n    z-index: 1;\n  }\n  .container {\n    max-width: 1160px;\n    margin: 0 auto;\n    padding: 0 1.5rem;\n  }\n  section {\n    padding: 6rem 0;\n    position: relative;\n  }\n  .section-header {\n    margin-bottom: 3.2rem;\n    max-width: 720px;\n  }\n  .eyebrow {\n    font-family: var(--font-mono);\n    font-size: 0.78rem;\n    text-transform: uppercase;\n    letter-spacing: 0.16em;\n    color: var(--accent-cyan);\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    margin-bottom: 0.75rem;\n  }\n  .eyebrow::before {\n    content: \"//\";\n    color: var(--accent-amber);\n  }\n  .section-title {\n    font-size: clamp(1.65rem, 3.2vw, 2.5rem);\n    line-height: 1.25;\n    font-weight: 800;\n    letter-spacing: -0.01em;\n    margin-bottom: 1rem;\n  }\n  .section-lead {\n    color: var(--text-secondary);\n    font-size: 1.02rem;\n  }\n\n  /* Reveal Animation System */\n  .reveal {\n    opacity: 0;\n    transform: translateY(28px);\n    transition: opacity 0.75s var(--ease-out-expo), transform 0.75s var(--ease-out-expo);\n  }\n  .reveal.is-visible {\n    opacity: 1;\n    transform: translateY(0);\n  }\n  .delay-1 { transition-delay: 0.1s; }\n  .delay-2 { transition-delay: 0.2s; }\n  .delay-3 { transition-delay: 0.3s; }\n\n  /* HERO SECTION */\n  .hero {\n    min-height: 100vh;\n    padding-top: 6.5rem;\n    padding-bottom: 4rem;\n    display: flex;\n    align-items: center;\n    position: relative;\n  }\n  .hero-grid {\n    display: grid;\n    grid-template-columns: 1.08fr 0.92fr;\n    gap: 2.5rem;\n    align-items: center;\n  }\n  .hero-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.6rem;\n    padding: 0.35rem 0.85rem;\n    background: rgba(0, 240, 255, 0.08);\n    border: 1px solid rgba(0, 240, 255, 0.28);\n    border-radius: 6px;\n    font-family: var(--font-mono);\n    font-size: 0.78rem;\n    color: var(--accent-cyan);\n    margin-bottom: 1.25rem;\n  }\n  .hero-title {\n    font-size: clamp(2.1rem, 4.4vw, 3.6rem);\n    font-weight: 900;\n    line-height: 1.18;\n    letter-spacing: -0.02em;\n    margin-bottom: 1.25rem;\n  }\n  .hero-title .highlight {\n    background: linear-gradient(95deg, #ffffff 0%, var(--accent-cyan) 55%, var(--accent-amber) 100%);\n    -webkit-background-clip: text;\n    background-clip: text;\n    color: transparent;\n  }\n  .hero-description {\n    font-size: clamp(1rem, 1.4vw, 1.14rem);\n    color: var(--text-secondary);\n    margin-bottom: 2rem;\n    max-width: 56ch;\n  }\n  .hero-actions {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 1rem;\n    align-items: center;\n    margin-bottom: 2.2rem;\n  }\n  .btn-primary {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.65rem;\n    padding: 0.9rem 1.6rem;\n    background: var(--accent-cyan);\n    color: #04080e;\n    font-weight: 800;\n    font-size: 0.95rem;\n    border-radius: 8px;\n    text-decoration: none;\n    border: 1px solid var(--accent-cyan);\n    box-shadow: 0 0 24px rgba(0, 240, 255, 0.3);\n    transition: transform 0.2s var(--ease-out-expo), box-shadow 0.2s ease, background-color 0.2s ease;\n    cursor: pointer;\n  }\n  .btn-primary:hover,\n  .btn-primary:focus-visible {\n    transform: translateY(-2px);\n    box-shadow: 0 0 34px rgba(0, 240, 255, 0.55);\n    background: #38f5ff;\n    outline: none;\n  }\n  .btn-secondary {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    padding: 0.9rem 1.4rem;\n    background: rgba(255, 255, 255, 0.03);\n    color: var(--text-primary);\n    font-weight: 700;\n    font-size: 0.92rem;\n    border-radius: 8px;\n    text-decoration: none;\n    border: 1px solid var(--border-dim);\n    transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;\n  }\n  .btn-secondary:hover,\n  .btn-secondary:focus-visible {\n    border-color: var(--accent-amber);\n    background: rgba(255, 184, 0, 0.08);\n    transform: translateY(-2px);\n    outline: none;\n  }\n  .hero-meta {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 0.75rem;\n    padding-top: 1.25rem;\n    border-top: 1px solid var(--border-dim);\n  }\n  .meta-item {\n    font-size: 0.8rem;\n    color: var(--text-secondary);\n  }\n  .meta-item strong {\n    display: block;\n    font-family: var(--font-mono);\n    color: var(--text-primary);\n    font-size: 0.85rem;\n    margin-bottom: 0.15rem;\n  }\n\n  /* Hero Visual Stage (Canvas + Interactive Console) */\n  .hero-stage {\n    position: relative;\n    background: linear-gradient(145deg, rgba(21, 28, 44, 0.85), rgba(10, 14, 22, 0.95));\n    border: 1px solid rgba(0, 240, 255, 0.25);\n    border-radius: 16px;\n    padding: 1.25rem;\n    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.65), var(--glow-cyan);\n    overflow: hidden;\n  }\n  .stage-topbar {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding-bottom: 0.85rem;\n    margin-bottom: 0.85rem;\n    border-bottom: 1px solid var(--border-dim);\n    font-family: var(--font-mono);\n    font-size: 0.75rem;\n    color: var(--text-secondary);\n  }\n  .window-dots {\n    display: flex;\n    gap: 6px;\n  }\n  .window-dots span {\n    width: 9px;\n    height: 9px;\n    border-radius: 50%;\n    background: rgba(255, 255, 255, 0.2);\n  }\n  .window-dots span:nth-child(1) { background: #f43f5e; }\n  .window-dots span:nth-child(2) { background: #ffb800; }\n  .window-dots span:nth-child(3) { background: #10b981; }\n\n  .canvas-wrapper {\n    position: relative;\n    height: 230px;\n    border-radius: 10px;\n    background: #06080d;\n    border: 1px solid rgba(255, 255, 255, 0.07);\n    overflow: hidden;\n    margin-bottom: 1rem;\n  }\n  #neuralCanvas {\n    width: 100%;\n    height: 100%;\n    display: block;\n  }\n  .canvas-overlay-badge {\n    position: absolute;\n    bottom: 10px;\n    left: 12px;\n    right: 12px;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    pointer-events: none;\n    font-family: var(--font-mono);\n    font-size: 0.7rem;\n    color: var(--text-secondary);\n    background: rgba(7, 9, 14, 0.75);\n    backdrop-filter: blur(6px);\n    padding: 0.35rem 0.65rem;\n    border-radius: 6px;\n    border: 1px solid rgba(255, 255, 255, 0.08);\n  }\n  .node-indicator {\n    color: var(--accent-cyan);\n    font-weight: 700;\n  }\n\n  /* Local Prompt Simulator inside Hero */\n  .sim-panel {\n    background: rgba(7, 9, 14, 0.85);\n    border: 1px solid var(--border-dim);\n    border-radius: 10px;\n    padding: 0.9rem;\n  }\n  .sim-tabs {\n    display: flex;\n    gap: 0.4rem;\n    margin-bottom: 0.75rem;\n    flex-wrap: wrap;\n  }\n  .sim-tab {\n    background: rgba(255, 255, 255, 0.04);\n    border: 1px solid var(--border-dim);\n    color: var(--text-secondary);\n    font-family: var(--font-sans);\n    font-size: 0.75rem;\n    font-weight: 600;\n    padding: 0.3rem 0.65rem;\n    border-radius: 6px;\n    cursor: pointer;\n    transition: all 0.2s ease;\n  }\n  .sim-tab:hover,\n  .sim-tab:focus-visible {\n    border-color: var(--accent-cyan);\n    color: var(--text-primary);\n    outline: none;\n  }\n  .sim-tab.active {\n    background: rgba(0, 240, 255, 0.14);\n    border-color: var(--accent-cyan);\n    color: var(--accent-cyan);\n  }\n  .sim-output {\n    font-family: var(--font-mono);\n    font-size: 0.78rem;\n    line-height: 1.55;\n    min-height: 4.8em;\n    color: var(--text-primary);\n  }\n  .sim-prompt-line {\n    color: var(--accent-amber);\n    margin-bottom: 0.25rem;\n  }\n  .sim-response-line {\n    color: #d1fae5;\n  }\n\n  /* SECTION 1: 3 CORE VALUES */\n  .values-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 1.5rem;\n  }\n  .value-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border-dim);\n    border-radius: 14px;\n    padding: 2rem 1.6rem;\n    position: relative;\n    overflow: hidden;\n    transition: transform 0.3s var(--ease-out-expo), border-color 0.3s ease, box-shadow 0.3s ease;\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n  }\n  .value-card::before {\n    content: \"\";\n    position: absolute;\n    top: 0;\n    left: 0;\n    right: 0;\n    height: 3px;\n    background: linear-gradient(90deg, var(--accent-cyan), transparent);\n    opacity: 0.4;\n    transition: opacity 0.3s ease;\n  }\n  .value-card:hover,\n  .value-card:focus-within {\n    transform: translateY(-6px);\n    border-color: var(--border-bright);\n    box-shadow: var(--glow-cyan);\n  }\n  .value-card:hover::before,\n  .value-card:focus-within::before {\n    opacity: 1;\n  }\n  .value-icon-box {\n    width: 52px;\n    height: 52px;\n    border-radius: 12px;\n    background: rgba(0, 240, 255, 0.08);\n    border: 1px solid rgba(0, 240, 255, 0.25);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    margin-bottom: 1.35rem;\n    color: var(--accent-cyan);\n  }\n  .value-card:nth-child(2) .value-icon-box {\n    background: rgba(255, 184, 0, 0.08);\n    border-color: rgba(255, 184, 0, 0.28);\n    color: var(--accent-amber);\n  }\n  .value-card:nth-child(3) .value-icon-box {\n    background: rgba(16, 185, 129, 0.08);\n    border-color: rgba(16, 185, 129, 0.28);\n    color: var(--accent-emerald);\n  }\n  .value-num {\n    font-family: var(--font-mono);\n    font-size: 0.75rem;\n    color: var(--text-muted);\n    margin-bottom: 0.4rem;\n    display: block;\n  }\n  .value-title {\n    font-size: 1.25rem;\n    font-weight: 800;\n    margin-bottom: 0.85rem;\n    color: var(--text-primary);\n  }\n  .value-desc {\n    color: var(--text-secondary);\n    font-size: 0.94rem;\n    margin-bottom: 1.4rem;\n  }\n  .value-tag {\n    font-family: var(--font-mono);\n    font-size: 0.74rem;\n    color: var(--text-secondary);\n    padding-top: 0.9rem;\n    border-top: 1px dashed var(--border-dim);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n  }\n\n  /* SECTION 2: USE CASES (Interactive Workbench) */\n  .usecase-workbench {\n    background: var(--bg-surface);\n    border: 1px solid var(--border-dim);\n    border-radius: 16px;\n    overflow: hidden;\n    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.45);\n  }\n  .workbench-nav {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    border-bottom: 1px solid var(--border-dim);\n    background: rgba(7, 9, 14, 0.6);\n  }\n  .wb-tab {\n    padding: 1.25rem 1rem;\n    background: transparent;\n    border: none;\n    border-bottom: 3px solid transparent;\n    color: var(--text-secondary);\n    font-family: var(--font-sans);\n    font-size: 0.98rem;\n    font-weight: 700;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 0.6rem;\n    transition: all 0.25s ease;\n  }\n  .wb-tab:hover,\n  .wb-tab:focus-visible {\n    color: var(--text-primary);\n    background: rgba(255, 255, 255, 0.02);\n    outline: none;\n  }\n  .wb-tab[aria-selected=\"true\"] {\n    color: var(--accent-cyan);\n    border-bottom-color: var(--accent-cyan);\n    background: rgba(0, 240, 255, 0.05);\n  }\n  .workbench-body {\n    padding: 2.4rem;\n  }\n  .wb-panel {\n    display: none;\n    grid-template-columns: 1fr 1fr;\n    gap: 2rem;\n    align-items: center;\n    animation: fadeSlide 0.4s var(--ease-out-expo);\n  }\n  .wb-panel.active {\n    display: grid;\n  }\n  .wb-info h3 {\n    font-size: 1.5rem;\n    margin-bottom: 0.85rem;\n    color: var(--text-primary);\n  }\n  .wb-info p {\n    color: var(--text-secondary);\n    margin-bottom: 1.25rem;\n    font-size: 0.96rem;\n  }\n  .wb-points {\n    list-style: none;\n    display: grid;\n    gap: 0.6rem;\n    margin-bottom: 1.25rem;\n  }\n  .wb-points li {\n    display: flex;\n    align-items: flex-start;\n    gap: 0.6rem;\n    font-size: 0.9rem;\n    color: var(--text-primary);\n  }\n  .wb-points li::before {\n    content: \"▹\";\n    color: var(--accent-cyan);\n    font-family: var(--font-mono);\n    font-weight: bold;\n  }\n  .wb-caveat {\n    padding: 0.75rem 1rem;\n    border-radius: 8px;\n    background: rgba(255, 184, 0, 0.07);\n    border-left: 3px solid var(--accent-amber);\n    font-size: 0.84rem;\n    color: #fde68a;\n  }\n  .wb-visual {\n    background: #070a10;\n    border: 1px solid var(--border-dim);\n    border-radius: 12px;\n    padding: 1.4rem;\n    font-family: var(--font-mono);\n    font-size: 0.82rem;\n    position: relative;\n  }\n  .wb-visual-header {\n    display: flex;\n    justify-content: space-between;\n    color: var(--text-muted);\n    font-size: 0.74rem;\n    padding-bottom: 0.65rem;\n    margin-bottom: 0.85rem;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n  }\n  .code-block-line {\n    display: block;\n    margin-bottom: 0.45rem;\n    color: var(--text-secondary);\n  }\n  .code-block-line .kw { color: var(--accent-cyan); }\n  .code-block-line .str { color: var(--accent-amber); }\n  .code-block-line .ok { color: var(--accent-emerald); }\n\n  /* SECTION 3: 4-STEP ROADMAP */\n  .steps-timeline {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.25rem;\n    position: relative;\n  }\n  .step-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border-dim);\n    border-radius: 14px;\n    padding: 1.75rem 1.35rem;\n    position: relative;\n    transition: border-color 0.3s ease, transform 0.3s var(--ease-out-expo);\n    display: flex;\n    flex-direction: column;\n  }\n  .step-card:hover,\n  .step-card:focus-within {\n    border-color: var(--accent-cyan);\n    transform: translateY(-5px);\n  }\n  .step-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    margin-bottom: 1.1rem;\n  }\n  .step-badge {\n    font-family: var(--font-mono);\n    font-size: 0.78rem;\n    font-weight: 700;\n    padding: 0.25rem 0.65rem;\n    border-radius: 6px;\n    background: rgba(0, 240, 255, 0.12);\n    color: var(--accent-cyan);\n    border: 1px solid rgba(0, 240, 255, 0.3);\n  }\n  .step-arrow {\n    color: var(--text-muted);\n    font-family: var(--font-mono);\n  }\n  .step-title {\n    font-size: 1.12rem;\n    font-weight: 800;\n    margin-bottom: 0.65rem;\n    color: var(--text-primary);\n  }\n  .step-desc {\n    font-size: 0.88rem;\n    color: var(--text-secondary);\n    flex-grow: 1;\n    margin-bottom: 1rem;\n  }\n  .step-check {\n    background: rgba(7, 9, 14, 0.65);\n    border: 1px solid var(--border-dim);\n    border-radius: 8px;\n    padding: 0.6rem 0.75rem;\n    font-size: 0.78rem;\n    color: var(--text-secondary);\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    cursor: pointer;\n    user-select: none;\n    transition: border-color 0.2s ease, color 0.2s ease;\n  }\n  .step-check input {\n    accent-color: var(--accent-cyan);\n    width: 15px;\n    height: 15px;\n    cursor: pointer;\n  }\n  .step-check:hover {\n    border-color: rgba(0, 240, 255, 0.4);\n    color: var(--text-primary);\n  }\n  .readiness-bar-wrap {\n    margin-top: 2rem;\n    background: var(--bg-surface);\n    border: 1px solid var(--border-dim);\n    border-radius: 12px;\n    padding: 1.25rem 1.5rem;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 1.5rem;\n    flex-wrap: wrap;\n  }\n  .readiness-label {\n    font-size: 0.9rem;\n    font-weight: 700;\n    display: flex;\n    align-items: center;\n    gap: 0.75rem;\n  }\n  .readiness-meter {\n    flex: 1;\n    min-width: 200px;\n    height: 10px;\n    background: #07090e;\n    border-radius: 999px;\n    overflow: hidden;\n    border: 1px solid var(--border-dim);\n  }\n  .readiness-fill {\n    height: 100%;\n    width: 25%;\n    background: linear-gradient(90deg, var(--accent-cyan), var(--accent-emerald));\n    transition: width 0.35s var(--ease-out-expo);\n  }\n  .readiness-status {\n    font-family: var(--font-mono);\n    font-size: 0.82rem;\n    color: var(--accent-cyan);\n  }\n\n  /* SECTION 4: CAUTIONS & REALISTIC EXPECTATIONS */\n  .caution-panel {\n    background: linear-gradient(160deg, rgba(21, 28, 44, 0.9), rgba(14, 19, 29, 0.95));\n    border: 1px solid rgba(255, 184, 0, 0.35);\n    border-radius: 16px;\n    padding: 2.5rem;\n    position: relative;\n  }\n  .caution-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 1.5rem;\n    margin-top: 1.8rem;\n  }\n  .caution-item {\n    background: rgba(7, 9, 14, 0.7);\n    border: 1px solid var(--border-dim);\n    border-left: 3px solid var(--accent-amber);\n    border-radius: 10px;\n    padding: 1.35rem;\n    transition: transform 0.25s ease, border-color 0.25s ease;\n  }\n  .caution-item:hover,\n  .caution-item:focus-within {\n    transform: translateY(-3px);\n    border-color: var(--accent-amber);\n  }\n  .caution-item h3 {\n    font-size: 1.05rem;\n    font-weight: 800;\n    margin-bottom: 0.6rem;\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    color: #fef3c7;\n  }\n  .caution-item p {\n    font-size: 0.88rem;\n    color: var(--text-secondary);\n    line-height: 1.65;\n  }\n\n  /* Footer */\n  .site-footer {\n    border-top: 1px solid var(--border-dim);\n    padding: 3rem 0;\n    background: #05070b;\n    font-size: 0.84rem;\n    color: var(--text-muted);\n  }\n  .footer-inner {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 1rem;\n  }\n\n  /* Keyframes */\n  @keyframes pulseRing {\n    0% { transform: scale(0.9); opacity: 0.8; }\n    70% { transform: scale(1.7); opacity: 0; }\n    100% { transform: scale(1.7); opacity: 0; }\n  }\n  @keyframes fadeSlide {\n    from { opacity: 0; transform: translateY(10px); }\n    to { opacity: 1; transform: translateY(0); }\n  }\n\n  /* Responsive Breakpoints (1024x768 & 390x844 verified) */\n  @media (max-width: 1024px) {\n    .hero-grid {\n      grid-template-columns: 1fr;\n      gap: 2rem;\n    }\n    .steps-timeline {\n      grid-template-columns: repeat(2, 1fr);\n    }\n    .values-grid,\n    .caution-grid {\n      grid-template-columns: repeat(3, 1fr);\n      gap: 1rem;\n    }\n  }\n\n  @media (max-width: 768px) {\n    section {\n      padding: 4rem 0;\n    }\n    .nav-links {\n      display: none;\n    }\n    .hero {\n      padding-top: 5.2rem;\n    }\n    .hero-meta {\n      grid-template-columns: 1fr;\n      gap: 0.6rem;\n    }\n    .values-grid,\n    .steps-timeline,\n    .caution-grid,\n    .wb-panel.active {\n      grid-template-columns: 1fr;\n    }\n    .workbench-nav {\n      grid-template-columns: 1fr;\n    }\n    .workbench-body {\n      padding: 1.35rem;\n    }\n    .caution-panel {\n      padding: 1.5rem 1.2rem;\n    }\n  }\n\n  /* Prefers Reduced Motion Compliance */\n  @media (prefers-reduced-motion: reduce) {\n    html {\n      scroll-behavior: auto;\n    }\n    *, *::before, *::after {\n      animation-duration: 0.01ms !important;\n      animation-iteration-count: 1 !important;\n      transition-duration: 0.01ms !important;\n    }\n    .reveal {\n      opacity: 1 !important;\n      transform: none !important;\n    }\n  }\n\u003c/style>\n\u003c/head>\n\u003cbody>\n\n\u003cdiv class=\"scroll-progress-track\" aria-hidden=\"true\">\n  \u003cdiv class=\"scroll-progress-bar\" id=\"scrollBar\">\u003c/div>\n\u003c/div>\n\n\u003cdiv class=\"grid-backdrop\" aria-hidden=\"true\">\u003c/div>\n\n\u003cheader class=\"site-header\">\n  \u003cdiv class=\"header-inner\">\n    \u003ca href=\"#top\" class=\"brand\">\n      \u003cspan class=\"brand-dot\" aria-hidden=\"true\">\u003c/span>\n      \u003cspan>LOCAL_LLM // GUIDE\u003c/span>\n    \u003c/a>\n    \u003cnav aria-label=\"ページ内ナビゲーション\">\n      \u003cul class=\"nav-links\">\n        \u003cli>\u003ca href=\"#values\">3つの魅力\u003c/a>\u003c/li>\n        \u003cli>\u003ca href=\"#usecases\">想定用途\u003c/a>\u003c/li>\n        \u003cli>\u003ca href=\"#steps\">導入の流れ\u003c/a>\u003c/li>\n        \u003cli>\u003ca href=\"#cautions\">注意点\u003c/a>\u003c/li>\n      \u003c/ul>\n    \u003c/nav>\n    \u003cdiv class=\"status-pill\" aria-label=\"ローカル完結コンセプト紹介\">\n      ON-DEVICE OPTION\n    \u003c/div>\n  \u003c/div>\n\u003c/header>\n\n\u003cmain id=\"top\">\n  \u003c!-- HERO SECTION -->\n  \u003csection class=\"hero\">\n    \u003cdiv class=\"container\">\n      \u003cdiv class=\"hero-grid\">\n        \u003cdiv class=\"hero-copy reveal is-visible\">\n          \u003cdiv class=\"hero-badge\">\n            \u003cspan>LOCAL EXECUTION PARADIGM\u003c/span>\n          \u003c/div>\n          \u003ch1 class=\"hero-title\">\n            生成AIを、\u003cbr>\n            \u003cspan class=\"highlight\">自分のPC・手元の計算機\u003c/span>で動かすという選択肢。\n          \u003c/h1>\n          \u003cp class=\"hero-description\">\n            クラウド上のAIサービスを使ったことがあるなら、次の一歩は「手元での実行」です。特定製品の売り込みではなく、あなたの計算機資源でモデルを選び、データの流れを自ら設計する新しい体験を紹介します。\n          \u003c/p>\n          \u003cdiv class=\"hero-actions\">\n            \u003ca href=\"#steps\" class=\"btn-primary\">\n              \u003cspan>導入の4ステップを見る\u003c/span>\n              \u003csvg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" aria-hidden=\"true\">\n                \u003cpath d=\"M12 5v14M19 12l-7 7-7-7\"/>\n              \u003c/svg>\n            \u003c/a>\n            \u003ca href=\"#usecases\" class=\"btn-secondary\">\n              \u003cspan>想定用途を試す\u003c/span>\n            \u003c/a>\n          \u003c/div>\n          \u003cdiv class=\"hero-meta\">\n            \u003cdiv class=\"meta-item\">\n              \u003cstrong>01 / 自由な実験\u003c/strong>\n              手元で気兼ねなく試行錯誤\n            \u003c/div>\n            \u003cdiv class=\"meta-item\">\n              \u003cstrong>02 / モデル選択\u003c/strong>\n              用途や機器に合わせて選ぶ\n            \u003c/div>\n            \u003cdiv class=\"meta-item\">\n              \u003cstrong>03 / データ設計\u003c/strong>\n              通信や保管の範囲を自分で管理\n            \u003c/div>\n          \u003c/div>\n        \u003c/div>\n\n        \u003c!-- Interactive Visual Stage -->\n        \u003cdiv class=\"hero-stage reveal delay-1 is-visible\" aria-label=\"ローカル推論イメージと対話プレビュー\">\n          \u003cdiv class=\"stage-topbar\">\n            \u003cdiv class=\"window-dots\" aria-hidden=\"true\">\n              \u003cspan>\u003c/span>\u003cspan>\u003c/span>\u003cspan>\u003c/span>\n            \u003c/div>\n            \u003cspan>LOCAL_RUNTIME_VISUALIZER\u003c/span>\n            \u003cspan id=\"motionStateLabel\">ACTIVE\u003c/span>\n          \u003c/div>\n\n          \u003cdiv class=\"canvas-wrapper\">\n            \u003ccanvas id=\"neuralCanvas\" width=\"520\" height=\"230\" aria-label=\"手元の計算機内部でトークンが処理される概念アニメーション\">\u003c/canvas>\n            \u003cdiv class=\"canvas-overlay-badge\">\n              \u003cspan>PROCESS: \u003cstrong class=\"node-indicator\">LOCAL WEIGHTS\u003c/strong>\u003c/span>\n              \u003cspan>NETWORK: \u003cstrong>SELF-MANAGED\u003c/strong>\u003c/span>\n            \u003c/div>\n          \u003c/div>\n\n          \u003cdiv class=\"sim-panel\">\n            \u003cdiv class=\"sim-tabs\" role=\"tablist\" aria-label=\"用途別ローカル実行イメージ\">\n              \u003cbutton type=\"button\" class=\"sim-tab active\" role=\"tab\" aria-selected=\"true\" data-sim=\"draft\">文章の下書き\u003c/button>\n              \u003cbutton type=\"button\" class=\"sim-tab\" role=\"tab\" aria-selected=\"false\" data-sim=\"code\">コードの相談\u003c/button>\n              \u003cbutton type=\"button\" class=\"sim-tab\" role=\"tab\" aria-selected=\"false\" data-sim=\"docs\">手元資料の整理\u003c/button>\n            \u003c/div>\n            \u003cdiv class=\"sim-output\" id=\"simOutput\" aria-live=\"polite\">\n              \u003cdiv class=\"sim-prompt-line\" id=\"simPrompt\">&gt; 企画書の導入段落を3パターン、簡潔なトーンで下書きして\u003c/div>\n              \u003cdiv class=\"sim-response-line\" id=\"simResponse\">手元のモデルで構成案を展開中… 外出し前のアイデア出しや推敲を、自分のペースで何度でも繰り返せます。\u003c/div>\n            \u003c/div>\n          \u003c/div>\n        \u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- SECTION 1: 3 CORE VALUES -->\n  \u003csection id=\"values\">\n    \u003cdiv class=\"container\">\n      \u003cdiv class=\"section-header reveal\">\n        \u003cspan class=\"eyebrow\">WHY RUN LOCALLY\u003c/span>\n        \u003ch2 class=\"section-title\">手元の計算機で動かす、3つの本質的な魅力\u003c/h2>\n        \u003cp class=\"section-lead\">\n          ブラウザ越しに完成されたサービスを借りるのとは異なり、自分の環境でモデルを動かすことには独自の面白さと設計の自由があります。\n        \u003c/p>\n      \u003c/div>\n\n      \u003cdiv class=\"values-grid\">\n        \u003carticle class=\"value-card reveal\" tabindex=\"0\">\n          \u003cdiv>\n            \u003cdiv class=\"value-icon-box\" aria-hidden=\"true\">\n              \u003csvg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n                \u003cpolygon points=\"12 2 2 7 12 12 22 7 12 2\"/>\n                \u003cpolyline points=\"2 17 12 22 22 17\"/>\n                \u003cpolyline points=\"2 12 12 17 22 12\"/>\n              \u003c/svg>\n            \u003c/div>\n            \u003cspan class=\"value-num\">VALUE // 01\u003c/span>\n            \u003ch3 class=\"value-title\">手元で試す楽しさ\u003c/h3>\n            \u003cp class=\"value-desc\">\n              自分のPC内部で言葉やコードが生成される仕組みに直接触れられます。設定やプロンプトを変えながら、手元の実験室のように何度でも試行錯誤を楽しめます。\n            \u003c/p>\n          \u003c/div>\n          \u003cdiv class=\"value-tag\">\n            \u003cspan>EXPERIMENTATION\u003c/span>\n            \u003cspan>→\u003c/span>\n          \u003c/div>\n        \u003c/article>\n\n        \u003carticle class=\"value-card reveal delay-1\" tabindex=\"0\">\n          \u003cdiv>\n            \u003cdiv class=\"value-icon-box\" aria-hidden=\"true\">\n              \u003csvg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n                \u003ccircle cx=\"12\" cy=\"12\" r=\"3\"/>\n                \u003cpath d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"/>\n              \u003c/svg>\n            \u003c/div>\n            \u003cspan class=\"value-num\">VALUE // 02\u003c/span>\n            \u003ch3 class=\"value-title\">用途に合わせてモデルを選ぶ自由\u003c/h3>\n            \u003cp class=\"value-desc\">\n              軽快な応答を重視する小さなモデルから、特定分野や日本語表現に配慮したモデルまで、自分の目的とマシンの余裕に合わせて自由に切り替えられます。\n            \u003c/p>\n          \u003c/div>\n          \u003cdiv class=\"value-tag\">\n            \u003cspan>MODEL FLEXIBILITY\u003c/span>\n            \u003cspan>→\u003c/span>\n          \u003c/div>\n        \u003c/article>\n\n        \u003carticle class=\"value-card reveal delay-2\" tabindex=\"0\">\n          \u003cdiv>\n            \u003cdiv class=\"value-icon-box\" aria-hidden=\"true\">\n              \u003csvg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n                \u003crect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\" ry=\"2\"/>\n                \u003cpath d=\"M7 11V7a5 5 0 0 1 10 0v4\"/>\n              \u003c/svg>\n            \u003c/div>\n            \u003cspan class=\"value-num\">VALUE // 03\u003c/span>\n            \u003ch3 class=\"value-title\">データの扱いを自分で設計できる\u003c/h3>\n            \u003cp class=\"value-desc\">\n              どのファイルを読み込ませ、どこに履歴を残し、外部通信を許可するか遮断するかをブラックボックス任せにせず、自分自身の設計下でコントロールできます。\n            \u003c/p>\n          \u003c/div>\n          \u003cdiv class=\"value-tag\">\n            \u003cspan>SELF-GOVERNED DATA\u003c/span>\n            \u003cspan>→\u003c/span>\n          \u003c/div>\n        \u003c/article>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- SECTION 2: USE CASES -->\n  \u003csection id=\"usecases\">\n    \u003cdiv class=\"container\">\n      \u003cdiv class=\"section-header reveal\">\n        \u003cspan class=\"eyebrow\">PRACTICAL SCENARIOS\u003c/span>\n        \u003ch2 class=\"section-title\">ローカルLLMの主な想定用途\u003c/h2>\n        \u003cp class=\"section-lead\">\n          日常的な思考の壁打ちや下準備に力を発揮します。なお、処理の成功や出力の精度は、選ぶ用途とモデルの特性に大きく依存します。\n        \u003c/p>\n      \u003c/div>\n\n      \u003cdiv class=\"usecase-workbench reveal\">\n        \u003cdiv class=\"workbench-nav\" role=\"tablist\" aria-label=\"想定用途の切り替え\">\n          \u003cbutton type=\"button\" class=\"wb-tab\" role=\"tab\" aria-selected=\"true\" aria-controls=\"panel-draft\" id=\"tab-draft\" data-wb=\"draft\">\n            \u003cspan>01. 文章の下書き\u003c/span>\n          \u003c/button>\n          \u003cbutton type=\"button\" class=\"wb-tab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"panel-code\" id=\"tab-code\" data-wb=\"code\">\n            \u003cspan>02. コードの相談\u003c/span>\n          \u003c/button>\n          \u003cbutton type=\"button\" class=\"wb-tab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"panel-docs\" id=\"tab-docs\" data-wb=\"docs\">\n            \u003cspan>03. 手元資料の整理\u003c/span>\n          \u003c/button>\n        \u003c/div>\n\n        \u003cdiv class=\"workbench-body\">\n          \u003c!-- Panel 1 -->\n          \u003cdiv class=\"wb-panel active\" id=\"panel-draft\" role=\"tabpanel\" aria-labelledby=\"tab-draft\">\n            \u003cdiv class=\"wb-info\">\n              \u003ch3>文章の下書き・構成の壁打ち\u003c/h3>\n              \u003cp>\n                メールの文面、企画メモの構成案、ブログ記事の見出し整理など、白紙の状態からたたき台を作る工程を手元で素早く回せます。\n              \u003c/p>\n              \u003cul class=\"wb-points\">\n                \u003cli>表現のトーン変更や言い換え案の列挙\u003c/li>\n                \u003cli>長文を書く前のアウトライン作成\u003c/li>\n                \u003cli>未公開のアイデアメモをもとにした推敲\u003c/li>\n              \u003c/ul>\n              \u003cdiv class=\"wb-caveat\">\n                ※ 事実関係の正確性や自然な言い回しは、選択したモデルの得意領域やサイズに依存します。最終確認は人間が行いましょう。\n              \u003c/div>\n            \u003c/div>\n            \u003cdiv class=\"wb-visual\" aria-label=\"文章下書きの実行イメージ\">\n              \u003cdiv class=\"wb-visual-header\">\n                \u003cspan>TASK: DRAFTING\u003c/span>\n                \u003cspan>MODE: INTERACTIVE\u003c/span>\n              \u003c/div>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"kw\">[入力]\u003c/span> 社内勉強会の案内文を、参加しやすい雰囲気で300字程度にまとめて。\u003c/span>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"str\">[処理]\u003c/span> 見出し構造と要点を抽出中...\u003c/span>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"ok\">[出力例]\u003c/span> 「はじめてのローカル環境体験会のお知らせ」として、対象者・持ち物・ゴールを整理した下書きを生成しました。\u003c/span>\n            \u003c/div>\n          \u003c/div>\n\n          \u003c!-- Panel 2 -->\n          \u003cdiv class=\"wb-panel\" id=\"panel-code\" role=\"tabpanel\" aria-labelledby=\"tab-code\">\n            \u003cdiv class=\"wb-info\">\n              \u003ch3>コードの相談・スクリプト補助\u003c/h3>\n              \u003cp>\n                ちょっとした自動化スクリプトの雛形作成、エラーメッセージの読み解き、正規表現やコマンドの組み立て相談などに活用できます。\n              \u003c/p>\n              \u003cul class=\"wb-points\">\n                \u003cli>関数単位のリファクタリング案やコメント付与\u003c/li>\n                \u003cli>定型処理（CSV整形やファイル一括処理）の試作\u003c/li>\n                \u003cli>コード向けの学習を経た専用モデルの選択も可能\u003c/li>\n              \u003c/ul>\n              \u003cdiv class=\"wb-caveat\">\n                ※ 生成されたコードがそのまま動作するとは限りません。成功や精度はモデルと課題の複雑さに依存するため、手元でのテストが必須です。\n              \u003c/div>\n            \u003c/div>\n            \u003cdiv class=\"wb-visual\" aria-label=\"コード相談の実行イメージ\">\n              \u003cdiv class=\"wb-visual-header\">\n                \u003cspan>TASK: CODE ASSIST\u003c/span>\n                \u003cspan>MODE: CODING MODEL\u003c/span>\n              \u003c/div>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"kw\">[入力]\u003c/span> フォルダ内のMarkdownから見出し行だけ抽出するPythonコードは？\u003c/span>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"str\">[処理]\u003c/span> 標準ライブラリ pathlib を使った構成を選択...\u003c/span>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"ok\">[出力例]\u003c/span> ファイル走査と行頭判定のサンプルコード、および例外処理のポイントを提示しました。\u003c/span>\n            \u003c/div>\n          \u003c/div>\n\n          \u003c!-- Panel 3 -->\n          \u003cdiv class=\"wb-panel\" id=\"panel-docs\" role=\"tabpanel\" aria-labelledby=\"tab-docs\">\n            \u003cdiv class=\"wb-info\">\n              \u003ch3>手元資料の整理・要約\u003c/h3>\n              \u003cp>\n                日々たまっていく自分のテキストメモ、議事録の下書き、読書ノートなどを構造化し、見返しやすく整理する用途に向いています。\n              \u003c/p>\n              \u003cul class=\"wb-points\">\n                \u003cli>箇条書きメモからの「決定事項・TODO」抽出\u003c/li>\n                \u003cli>複数メモに散らばった論点のグループ分け\u003c/li>\n                \u003cli>手元のファイル構成に合わせたフォーマット変換\u003c/li>\n              \u003c/ul>\n              \u003cdiv class=\"wb-caveat\">\n                ※ 一度に読み込める文字量（コンテキスト長）や要約の精度は、モデル・機器のメモリ余裕・設定に依存します。\n              \u003c/div>\n            \u003c/div>\n            \u003cdiv class=\"wb-visual\" aria-label=\"手元資料整理の実行イメージ\">\n              \u003cdiv class=\"wb-visual-header\">\n                \u003cspan>TASK: LOCAL NOTES\u003c/span>\n                \u003cspan>MODE: STRUCTURING\u003c/span>\n              \u003c/div>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"kw\">[入力]\u003c/span> 雑多な打合せメモ3件から、今週やるべき作業項目だけを抜き出して。\u003c/span>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"str\">[処理]\u003c/span> テキスト断片を解析しアクション項目に分類...\u003c/span>\n              \u003cspan class=\"code-block-line\">\u003cspan class=\"ok\">[出力例]\u003c/span> 「確認事項」「作成タスク」「保留項目」の3カテゴリに整理したチェックリストを生成しました。\u003c/span>\n            \u003c/div>\n          \u003c/div>\n        \u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- SECTION 3: 4 STEPS TO START (CTA Target) -->\n  \u003csection id=\"steps\">\n    \u003cdiv class=\"container\">\n      \u003cdiv class=\"section-header reveal\">\n        \u003cspan class=\"eyebrow\">GETTING STARTED\u003c/span>\n        \u003ch2 class=\"section-title\">無理なく始める、導入の4ステップ\u003c/h2>\n        \u003cp class=\"section-lead\">\n          いきなり巨大な環境を作る必要はありません。順を追って確認し、まずは小さなモデルから手元で動かしてみるのが成功の近道です。\n        \u003c/p>\n      \u003c/div>\n\n      \u003cdiv class=\"steps-timeline\">\n        \u003carticle class=\"step-card reveal\">\n          \u003cdiv class=\"step-header\">\n            \u003cspan class=\"step-badge\">STEP 01\u003c/span>\n            \u003cspan class=\"step-arrow\" aria-hidden=\"true\">01/04\u003c/span>\n          \u003c/div>\n          \u003ch3 class=\"step-title\">用途を決める\u003c/h3>\n          \u003cp class=\"step-desc\">\n            「短文の下書き」「コードの断片相談」「手元メモの要約」など、最初に試したい具体的な用途を1つに絞ります。目的が明確だとモデル選びで迷いません。\n          \u003c/p>\n          \u003clabel class=\"step-check\">\n            \u003cinput type=\"checkbox\" class=\"step-toggle\" checked>\n            \u003cspan>試したい用途を1つ決めた\u003c/span>\n          \u003c/label>\n        \u003c/article>\n\n        \u003carticle class=\"step-card reveal delay-1\">\n          \u003cdiv class=\"step-header\">\n            \u003cspan class=\"step-badge\">STEP 02\u003c/span>\n            \u003cspan class=\"step-arrow\" aria-hidden=\"true\">02/04\u003c/span>\n          \u003c/div>\n          \u003ch3 class=\"step-title\">機器と必要メモリを確認する\u003c/h3>\n          \u003cp class=\"step-desc\">\n            手元のPCの搭載メモリ（RAM）やGPUメモリ（VRAM）、空きストレージ容量を確認します。余裕のあるメモリ範囲に収まるモデルを選ぶことが快適さの鍵です。\n          \u003c/p>\n          \u003clabel class=\"step-check\">\n            \u003cinput type=\"checkbox\" class=\"step-toggle\">\n            \u003cspan>PCのメモリ容量を確認した\u003c/span>\n          \u003c/label>\n        \u003c/article>\n\n        \u003carticle class=\"step-card reveal delay-2\">\n          \u003cdiv class=\"step-header\">\n            \u003cspan class=\"step-badge\">STEP 03\u003c/span>\n            \u003cspan class=\"step-arrow\" aria-hidden=\"true\">03/04\u003c/span>\n          \u003c/div>\n          \u003ch3 class=\"step-title\">利用条件を読んでモデルを選ぶ\u003c/h3>\n          \u003cp class=\"step-desc\">\n            公開されているモデルのライセンスや利用条件（商用可否・再配布条件・禁止用途など）を必ず確認し、自分の用途と機器スペックに合うモデルを選びます。\n          \u003c/p>\n          \u003clabel class=\"step-check\">\n            \u003cinput type=\"checkbox\" class=\"step-toggle\">\n            \u003cspan>利用条件とサイズを確認した\u003c/span>\n          \u003c/label>\n        \u003c/article>\n\n        \u003carticle class=\"step-card reveal delay-3\">\n          \u003cdiv class=\"step-header\">\n            \u003cspan class=\"step-badge\">STEP 04\u003c/span>\n            \u003cspan class=\"step-arrow\" aria-hidden=\"true\">04/04\u003c/span>\n          \u003c/div>\n          \u003ch3 class=\"step-title\">小さく試す\u003c/h3>\n          \u003cp class=\"step-desc\">\n            最初は軽量なモデルと短い入力から動かし、応答速度やメモリ消費の感覚をつかみます。手元で動く実感を得てから、設定やモデルを少しずつ調整しましょう。\n          \u003c/p>\n          \u003clabel class=\"step-check\">\n            \u003cinput type=\"checkbox\" class=\"step-toggle\">\n            \u003cspan>軽量モデルから実験開始\u003c/span>\n          \u003c/label>\n        \u003c/article>\n      \u003c/div>\n\n      \u003cdiv class=\"readiness-bar-wrap reveal\" aria-live=\"polite\">\n        \u003cdiv class=\"readiness-label\">\n          \u003cspan>導入準備チェック進捗\u003c/span>\n        \u003c/div>\n        \u003cdiv class=\"readiness-meter\" aria-hidden=\"true\">\n          \u003cdiv class=\"readiness-fill\" id=\"readinessFill\">\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"readiness-status\" id=\"readinessText\">1 / 4 STEP READY (ページ内シミュレーション)\u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- SECTION 4: CAUTIONS -->\n  \u003csection id=\"cautions\">\n    \u003cdiv class=\"container\">\n      \u003cdiv class=\"caution-panel reveal\">\n        \u003cspan class=\"eyebrow\">IMPORTANT NOTES\u003c/span>\n        \u003ch2 class=\"section-title\">導入前に知っておきたい3つの注意点\u003c/h2>\n        \u003cp class=\"section-lead\">\n          ローカルLLMは万能の魔法ではありません。手元で安全・快適に活用するために、以下の前提を正しく理解して設計しましょう。\n        \u003c/p>\n\n        \u003cdiv class=\"caution-grid\">\n          \u003cdiv class=\"caution-item\" tabindex=\"0\">\n            \u003ch3>\n              \u003csvg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\">\n                \u003ccircle cx=\"12\" cy=\"12\" r=\"10\"/>\u003cpolyline points=\"12 6 12 12 16 14\"/>\n              \u003c/svg>\n              速度と必要メモリの依存性\n            \u003c/h3>\n            \u003cp>\n              動作の速度と必要になるメモリ量は、選ぶモデルの規模や量子化形式、手元の機器（CPU/GPU/メモリ帯域）、さらにコンテキスト長などの設定に強く依存します。\n            \u003c/p>\n          \u003c/div>\n\n          \u003cdiv class=\"caution-item\" tabindex=\"0\">\n            \u003ch3>\n              \u003csvg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\">\n                \u003cpath d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/>\u003cpolyline points=\"14 2 14 8 20 8\"/>\n              \u003c/svg>\n              利用条件・ライセンスの違い\n            \u003c/h3>\n            \u003cp>\n              手元にダウンロードできるからといって、全モデルが無料・商用利用可能とは限りません。研究用途限定や独自規約を持つモデルもあるため、利用条件の確認が不可欠です。\n            \u003c/p>\n          \u003c/div>\n\n          \u003cdiv class=\"caution-item\" tabindex=\"0\">\n            \u003ch3>\n              \u003csvg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\">\n                \u003cpath d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/>\n              \u003c/svg>\n              通信と秘密保持の正しい理解\n            \u003c/h3>\n            \u003cp>\n              外部API連携やWeb検索機能、ツールの自動更新設定などによって通信が発生する場合があります。「ローカル実行だから自動的に完全な秘密保持が保証される」わけではない点に注意してください。\n            \u003c/p>\n          \u003c/div>\n        \u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\u003c/main>\n\n\u003cfooter class=\"site-footer\">\n  \u003cdiv class=\"container footer-inner\">\n    \u003cdiv>\n      \u003cstrong>LOCAL_LLM // CONCEPT GUIDE\u003c/strong> — 自分のPC・手元の計算機で動かす選択肢の紹介ページ（特定製品の販売サイトではありません）\n    \u003c/div>\n    \u003cdiv>\n      OFFLINE-FIRST DESIGN / NO EXTERNAL REQUESTS\n    \u003c/div>\n  \u003c/div>\n\u003c/footer>\n\n\u003cscript>\n  (function () {\n    // 1. Scroll Progress & Reveal Observer\n    const scrollBar = document.getElementById('scrollBar');\n    const reveals = document.querySelectorAll('.reveal');\n\n    function updateScrollProgress() {\n      const scrollTop = window.scrollY || document.documentElement.scrollTop;\n      const docHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;\n      const ratio = docHeight > 0 ? Math.min(100, Math.max(0, (scrollTop / docHeight) * 100)) : 0;\n      if (scrollBar) {\n        scrollBar.style.width = ratio.toFixed(1) + '%';\n      }\n    }\n    window.addEventListener('scroll', updateScrollProgress, { passive: true });\n    updateScrollProgress();\n\n    if ('IntersectionObserver' in window) {\n      const io = new IntersectionObserver((entries) => {\n        entries.forEach((entry) => {\n          if (entry.isIntersecting) {\n            entry.target.classList.add('is-visible');\n          }\n        });\n      }, { threshold: 0.14 });\n      reveals.forEach((el) => io.observe(el));\n    } else {\n      reveals.forEach((el) => el.classList.add('is-visible'));\n    }\n\n    // 2. Hero Prompt Simulator Tabs\n    const simData = {\n      draft: {\n        prompt: '> 企画書の導入段落を3パターン、簡潔なトーンで下書きして',\n        response: '手元のモデルで構成案を展開中… 外出し前のアイデア出しや推敲を、自分のペースで何度でも繰り返せます。'\n      },\n      code: {\n        prompt: '> ログファイルからエラー行だけ抽出するスクリプトの雛形を作って',\n        response: '手元の環境でコード断片を生成中… 用途に合ったモデルを選び、動作検証しながら相談を進められます。'\n      },\n      docs: {\n        prompt: '> 手元の会議メモ箇条書きから、今週のTODOと保留事項を整理して',\n        response: 'ローカル上のテキストを構造化中… データの扱い方や保存先を自分で設計しながら資料整理を行えます。'\n      }\n    };\n\n    const simTabs = document.querySelectorAll('.sim-tab');\n    const simPrompt = document.getElementById('simPrompt');\n    const simResponse = document.getElementById('simResponse');\n    let pulseBoost = 0;\n\n    simTabs.forEach((btn) => {\n      btn.addEventListener('click', () => {\n        const key = btn.getAttribute('data-sim');\n        if (!simData[key]) return;\n        simTabs.forEach((b) => {\n          b.classList.remove('active');\n          b.setAttribute('aria-selected', 'false');\n        });\n        btn.classList.add('active');\n        btn.setAttribute('aria-selected', 'true');\n        simPrompt.textContent = simData[key].prompt;\n        simResponse.textContent = simData[key].response;\n        pulseBoost = 1.0;\n      });\n    });\n\n    // 3. Workbench Use-Case Tabs\n    const wbTabs = document.querySelectorAll('.wb-tab');\n    const wbPanels = document.querySelectorAll('.wb-panel');\n\n    wbTabs.forEach((tab) => {\n      tab.addEventListener('click', () => {\n        const target = tab.getAttribute('data-wb');\n        wbTabs.forEach((t) => t.setAttribute('aria-selected', 'false'));\n        tab.setAttribute('aria-selected', 'true');\n        wbPanels.forEach((panel) => {\n          if (panel.id === 'panel-' + target) {\n            panel.classList.add('active');\n          } else {\n            panel.classList.remove('active');\n          }\n        });\n      });\n    });\n\n    // 4. 4-Step Interactive Readiness Checklist (Client-only, no transmission)\n    const stepToggles = document.querySelectorAll('.step-toggle');\n    const readinessFill = document.getElementById('readinessFill');\n    const readinessText = document.getElementById('readinessText');\n\n    function updateReadiness() {\n      let checkedCount = 0;\n      stepToggles.forEach((chk) => {\n        if (chk.checked) checkedCount++;\n      });\n      const total = stepToggles.length || 4;\n      const pct = Math.round((checkedCount / total) * 100);\n      if (readinessFill) readinessFill.style.width = pct + '%';\n      if (readinessText) {\n        readinessText.textContent = checkedCount + ' / ' + total + ' STEP READY (ページ内シミュレーション)';\n      }\n    }\n    stepToggles.forEach((chk) => chk.addEventListener('change', updateReadiness));\n    updateReadiness();\n\n    // 5. Hero Canvas Neural / Local Compute Visualizer (Respects prefers-reduced-motion)\n    const canvas = document.getElementById('neuralCanvas');\n    const motionLabel = document.getElementById('motionStateLabel');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const reduceMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');\n\n    const nodes = [\n      { x: 75,  y: 65,  layer: 0 },\n      { x: 75,  y: 115, layer: 0 },\n      { x: 75,  y: 165, layer: 0 },\n      { x: 195, y: 45,  layer: 1 },\n      { x: 195, y: 95,  layer: 1 },\n      { x: 195, y: 140, layer: 1 },\n      { x: 195, y: 185, layer: 1 },\n      { x: 325, y: 60,  layer: 2 },\n      { x: 325, y: 115, layer: 2 },\n      { x: 325, y: 170, layer: 2 },\n      { x: 445, y: 90,  layer: 3 },\n      { x: 445, y: 140, layer: 3 }\n    ];\n\n    const edges = [];\n    for (let i = 0; i \u003c nodes.length; i++) {\n      for (let j = i + 1; j \u003c nodes.length; j++) {\n        if (nodes[j].layer === nodes[i].layer + 1) {\n          edges.push({ from: nodes[i], to: nodes[j], phase: (i * 0.37 + j * 0.23) % 1 });\n        }\n      }\n    }\n\n    let pointer = { x: -999, y: -999 };\n    canvas.addEventListener('mousemove', (e) => {\n      const rect = canvas.getBoundingClientRect();\n      const scaleX = canvas.width / rect.width;\n      const scaleY = canvas.height / rect.height;\n      pointer.x = (e.clientX - rect.left) * scaleX;\n      pointer.y = (e.clientY - rect.top) * scaleY;\n    });\n    canvas.addEventListener('mouseleave', () => {\n      pointer.x = -999;\n      pointer.y = -999;\n    });\n\n    function drawFrame(time, isStatic) {\n      ctx.clearRect(0, 0, canvas.width, canvas.height);\n\n      // Subtle local hardware enclosure frame\n      ctx.strokeStyle = 'rgba(0, 240, 255, 0.14)';\n      ctx.lineWidth = 1;\n      ctx.strokeRect(24, 18, canvas.width - 48, canvas.height - 36);\n\n      // Draw connections\n      edges.forEach((edge) => {\n        ctx.beginPath();\n        ctx.moveTo(edge.from.x, edge.from.y);\n        ctx.lineTo(edge.to.x, edge.to.y);\n        ctx.strokeStyle = 'rgba(148, 163, 184, 0.16)';\n        ctx.lineWidth = 1;\n        ctx.stroke();\n\n        // Signal packet\n        const speed = 0.00045 + (pulseBoost * 0.0008);\n        const t = isStatic ? 0.5 : (time * speed + edge.phase) % 1;\n        const px = edge.from.x + (edge.to.x - edge.from.x) * t;\n        const py = edge.from.y + (edge.to.y - edge.from.y) * t;\n\n        ctx.beginPath();\n        ctx.arc(px, py, 2.2, 0, Math.PI * 2);\n        ctx.fillStyle = edge.to.layer === 3 ? '#ffb800' : '#00f0ff';\n        ctx.fill();\n      });\n\n      // Draw nodes\n      nodes.forEach((n, idx) => {\n        const dist = Math.hypot(pointer.x - n.x, pointer.y - n.y);\n        const hovered = dist \u003c 36;\n        const pulse = isStatic ? 0 : Math.sin(time * 0.003 + idx) * 1.5;\n        const radius = (hovered ? 7.5 : 5.2) + pulse * 0.35;\n\n        ctx.beginPath();\n        ctx.arc(n.x, n.y, radius + 4, 0, Math.PI * 2);\n        ctx.fillStyle = n.layer === 3 ? 'rgba(255, 184, 0, 0.15)' : 'rgba(0, 240, 255, 0.14)';\n        ctx.fill();\n\n        ctx.beginPath();\n        ctx.arc(n.x, n.y, radius, 0, Math.PI * 2);\n        ctx.fillStyle = n.layer === 3 ? '#ffb800' : (hovered ? '#ffffff' : '#00f0ff');\n        ctx.fill();\n      });\n\n      if (pulseBoost > 0) {\n        pulseBoost = Math.max(0, pulseBoost - 0.02);\n      }\n    }\n\n    let animId = null;\n    function loop(timestamp) {\n      drawFrame(timestamp, false);\n      animId = window.requestAnimationFrame(loop);\n    }\n\n    function handleMotionPreference() {\n      if (reduceMotionQuery.matches) {\n        if (animId) window.cancelAnimationFrame(animId);\n        if (motionLabel) motionLabel.textContent = 'STATIC (REDUCED MOTION)';\n        drawFrame(0, true);\n      } else {\n        if (motionLabel) motionLabel.textContent = 'ACTIVE';\n        if (animId) window.cancelAnimationFrame(animId);\n        animId = window.requestAnimationFrame(loop);\n      }\n    }\n\n    if (typeof reduceMotionQuery.addEventListener === 'function') {\n      reduceMotionQuery.addEventListener('change', handleMotionPreference);\n    }\n    handleMotionPreference();\n  })();\n\u003c/script>\n\u003c/body>\n\u003c/html>"};
